 	rcu_read_lock();
 	memcg = mem_cgroup_from_private_id(id);
 	if (memcg) {
-		mem_cgroup_swap_uncharge(memcg, nr);
+		/*
+		 * An xswap entry was not charged here; its backing, if any,
